   [99]={next_id=100, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Many years ago, I lived in another fortress city. Back then, I was just a little girl with all my limbs intact—someone who loved and cherished her own body.", msg_color="", msg_size=0, talker="Elsida", audio="", img="arts/ui/bg/story/storybg_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4511", 0, 0, 54.5, 184.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
